import threading,weakref,collections
class Memo:
    def __init__(self,max_entries=2):
        if type(max_entries) is not int or not 1<=max_entries<=8:raise ValueError('bounded entries per owner')
        self.limit=max_entries;self.lock=threading.RLock();self.owners=weakref.WeakKeyDictionary()
    def get(self,owner,key,compute):
        if not isinstance(key,str) or not 1<=len(key)<=32:raise ValueError('key')
        while True:
            with self.lock:
                state=self.owners.get(owner)
                if state is None:state={'values':collections.OrderedDict(),'running':{}};self.owners[owner]=state
                if key in state['values']:
                    state['values'].move_to_end(key);return state['values'][key]
                event=state['running'].get(key)
                if event is None:event=threading.Event();state['running'][key]=event;leader=True
                else:leader=False
            if leader:break
            event.wait()
        try:
            value=compute()
            if type(value) is not int:raise ValueError('only independent integer results')
            with self.lock:
                state['values'][key]=value;state['values'].move_to_end(key)
                while len(state['values'])>self.limit:state['values'].popitem(last=False)
            return value
        finally:
            with self.lock:state['running'].pop(key,None);event.set()
